(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  let wy = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  wx += Math.sin((y + wy) * 0.03 + t * 0.15) * 8;
  wy += Math.cos((x + wx) * 0.025 - t * 0.2) * 8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [240+Math.cos(t*0.45)*180*Math.cos(t*0.2), 120+Math.sin(t*0.45)*100*Math.sin(t*0.15), 0.05, 3.1],
    [240+Math.sin(t*0.7+3)*160, 120+Math.cos(t*0.5+2)*80, 0.11, 1.3]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  const act = aS/8, inh = iS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.15)+t*0.6)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4 + Math.sin(dist*0.08-ang*2+t*0.8)*0.15;
  const fine = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.1;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + fine)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const aS2 = Math.sin(Math.sqrt((sx*0.5-120)**2+(sy*0.5-60)**2)*0.15-t*1.8);
  const iS2 = Math.sin(Math.sqrt((sx*0.5+50)**2+(sy*0.5+30)**2)*0.12+t*1.2);
  const micro = Math.tanh((aS2 - iS2*0.6)*1.5)*0.15;
  const blend = reaction*0.6 + cell*0.2 + micro*0.2, v = blend*0.5+0.5;
  const pal = [[5,12,55],[12,45,95],[18,85,120],[25,140,130],[60,175,115],[160,195,75],[220,190,60],[230,140,55],[210,90,60],[170,50,65],[110,25,55],[50,15,50],[5,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i, sf = f*f*(3-2*f);
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const vig = 1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/350*0.15;
  const pulse = 0.92+Math.sin(t*0.8)*0.08;
  return [
    Math.min(255, Math.max(0, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge*vig*pulse))|0,
    Math.min(255, Math.max(0, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge*vig*pulse))|0,
    Math.min(255, Math.max(0, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge*vig*pulse))|0
  ];
}
